import pandas as pd
import numpy as np

df = pd.read_csv('/app/benchmark/data.csv', encoding='utf-8-sig')

# Generate chart data as JSON-like structures for embedding
import json

# 1. Bar chart: Average Star Rating by App
avg_star = df.groupby('App')['Star_Rating'].mean().sort_values(ascending=False)
star_data = {
    'labels': [a.replace('_', ' ') for a in avg_star.index.tolist()],
    'values': [round(v, 2) for v in avg_star.values.tolist()]
}

# 2. Bar chart: Mean Sentiment Polarity by App
avg_sent = df.groupby('App')['Sentiment_Polarity'].mean().sort_values(ascending=False)
sent_data = {
    'labels': [a.replace('_', ' ') for a in avg_sent.index.tolist()],
    'values': [round(v, 3) for v in avg_sent.values.tolist()]
}

# 3. Stacked bar: Theme distribution per app
theme_counts = df.groupby(['App', 'Review_Theme']).size().unstack(fill_value=0)
theme_pcts = theme_counts.div(theme_counts.sum(axis=1), axis=0) * 100
theme_pcts = theme_pcts.reindex(['ChatGPT', 'Claude', 'Google_Gemini', 'Microsoft_Copilot', 'Perplexity'])

theme_data = {
    'labels': [a.replace('_', ' ') for a in theme_pcts.index.tolist()],
    'datasets': []
}
colors = {
    'General': '#3498db',
    'Pricing/Subscription': '#e74c3c',
    'Bugs/Performance': '#f39c12',
    'Accuracy/Logic Issues': '#9b59b6'
}
for theme in ['General', 'Pricing/Subscription', 'Bugs/Performance', 'Accuracy/Logic Issues']:
    theme_data['datasets'].append({
        'label': theme,
        'data': [round(v, 1) for v in theme_pcts[theme].tolist()],
        'backgroundColor': colors[theme]
    })

# 4. Grouped bar: Complaint theme rates (non-General) per app
complaint_apps = ['ChatGPT', 'Claude', 'Google_Gemini', 'Microsoft_Copilot', 'Perplexity']
complaint_data = {
    'labels': [a.replace('_', ' ') for a in complaint_apps],
    'datasets': []
}
for theme in ['Pricing/Subscription', 'Bugs/Performance', 'Accuracy/Logic Issues']:
    vals = []
    for app in complaint_apps:
        subset = df[(df['App']==app) & (df['Review_Theme']==theme)]
        pct = len(subset) / len(df[df['App']==app]) * 100
        vals.append(round(pct, 2))
    complaint_data['datasets'].append({
        'label': theme,
        'data': vals,
        'backgroundColor': colors[theme]
    })

# 5. Mismatch rate per app
mismatch = df.groupby('App').apply(
    lambda x: (
        ((x['Star_Rating'] >= 4) & (x['Sentiment_Polarity'] < -0.05)) |
        ((x['Star_Rating'] <= 2) & (x['Sentiment_Polarity'] > 0.05))
    ).mean() * 100
).sort_values(ascending=False)

mismatch_data = {
    'labels': [a.replace('_', ' ') for a in mismatch.index.tolist()],
    'values': [round(v, 2) for v in mismatch.values.tolist()]
}

# 6. Rating distribution per app (stacked horizontal or grouped)
rating_dist = df.groupby(['App', 'Star_Rating']).size().unstack(fill_value=0)
rating_dist = rating_dist.reindex(['ChatGPT', 'Claude', 'Google_Gemini', 'Microsoft_Copilot', 'Perplexity'])
rating_dist_pct = rating_dist.div(rating_dist.sum(axis=1), axis=0) * 100

rating_data = {
    'labels': [a.replace('_', ' ') for a in rating_dist_pct.index.tolist()],
    'datasets': []
}
star_colors = ['#e74c3c', '#e67e22', '#f1c40f', '#2ecc71', '#27ae60']
for i, star in enumerate([1,2,3,4,5]):
    rating_data['datasets'].append({
        'label': f'{star} Star',
        'data': [round(v, 1) for v in rating_dist_pct[star].tolist()],
        'backgroundColor': star_colors[i]
    })

# 7. Word count by star rating
wc_by_star = df.groupby('Star_Rating')['Word_Count'].mean()
wc_data = {
    'labels': [f'{int(s)} Star' for s in wc_by_star.index.tolist()],
    'values': [round(v, 1) for v in wc_by_star.values.tolist()]
}

# 8. Engagement by theme
eng_theme = df.groupby('Review_Theme')['Thumbs_Up_Count'].mean().sort_values(ascending=False)
eng_data = {
    'labels': eng_theme.index.tolist(),
    'values': [round(v, 2) for v in eng_theme.values.tolist()]
}

# 9. Thumbs up by app
eng_app = df.groupby('App')['Thumbs_Up_Count'].mean().sort_values(ascending=False)
eng_app_data = {
    'labels': [a.replace('_', ' ') for a in eng_app.index.tolist()],
    'values': [round(v, 2) for v in eng_app.values.tolist()]
}

# 10. Sentiment polarity distribution (histogram bins) per app - we'll do boxplot-like stats
sent_stats = df.groupby('App')['Sentiment_Polarity'].agg(['min', 'max', 'mean', 'std']).reindex(
    ['ChatGPT', 'Claude', 'Google_Gemini', 'Microsoft_Copilot', 'Perplexity']
)
sent_stats_data = {
    'labels': [a.replace('_', ' ') for a in sent_stats.index.tolist()],
    'datasets': [
        {'label': 'Mean', 'data': [round(v, 3) for v in sent_stats['mean'].tolist()], 'backgroundColor': '#3498db'},
        {'label': 'Std Dev', 'data': [round(v, 3) for v in sent_stats['std'].tolist()], 'backgroundColor': '#e74c3c'}
    ]
}

# Save all chart data to a JSON file for reference
chart_data = {
    'star_rating': star_data,
    'sentiment_polarity': sent_data,
    'theme_distribution': theme_data,
    'complaint_themes': complaint_data,
    'mismatch_rate': mismatch_data,
    'rating_distribution': rating_data,
    'word_count_by_star': wc_data,
    'engagement_by_theme': eng_data,
    'engagement_by_app': eng_app_data,
    'sentiment_stats': sent_stats_data
}

with open('/app/output/chart_data.json', 'w') as f:
    json.dump(chart_data, f, indent=2)

print("Chart data saved.")
print(json.dumps(chart_data, indent=2))
